def clean(df):
    df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    df = df[df['species'] == 'Adelie']
    df = df[df['island'].isin(['Biscoe', 'Dream', 'Torgersen'])]
    return df

def answer(df):
    result = {}
    for island, group in df.groupby('island'):
        avg = group['bill_length_mm'].mean()
        result[island] = avg
    return result
